const event = $json.body ?? $json;
const payment = event.data?.object;
if (!event.id || !event.type || !payment) throw new Error('Invalid Stripe event payload');
const supported = ['payment_intent.succeeded', 'payment_intent.payment_failed'];
if (!supported.includes(event.type)) throw new Error(`Unsupported Stripe event: ${event.type}`);
const onboardingId = payment.metadata?.onboarding_id ?? '';
const sourceDealId = payment.metadata?.source_deal_id ?? '';
if (!onboardingId && !sourceDealId) throw new Error('Stripe metadata requires onboarding_id or source_deal_id');
const normalized = {
  provider: 'stripe', event_id: String(event.id), event_type: String(event.type),
  onboarding_id: String(onboardingId), source_deal_id: String(sourceDealId),
  requirement_key: 'deposit', result: event.type === 'payment_intent.succeeded' ? 'paid' : 'failed',
  external_object_id: String(payment.id ?? '')
};
return [{ json: { ...normalized, payload_base64: Buffer.from(JSON.stringify(normalized)).toString('base64') } }];
